from pathlib import Path
import boto3,json,shutil,hashlib
out=Path('tmp/registry-performance-release');artifact=out/'artifact';s=boto3.Session(profile_name='rfone-dev-login',region_name='us-east-1');v=json.loads(Path('tmp/registry-clover-release/state.json').read_text());service=s.client('apprunner').describe_service(ServiceArn=v['service_arn'])['Service'];assert service['Status']=='RUNNING';assert service['SourceConfiguration']['ImageRepository']['ImageIdentifier']==v['image'],'Live image changed; inspect before deploy';digest=s.client('ecr').describe_images(repositoryName='rfone-web',imageIds=[{'imageTag':v['tag']}])['imageDetails'][0]['imageDigest'];assert digest==v['image_digest'];(out/'baseline-service.json').write_text(json.dumps(service,default=str,indent=2))
for name in ('role_profile_routes.py','registry_clover.py','tests/test_registry_performance.py'):
 dst=artifact/'03 Software/RF-One Web'/name;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(Path('tmp/git-anagrafica-release/03 Software/RF-One Web')/name,dst)
(artifact/'Dockerfile').write_text('FROM '+v['image'].rsplit(':',1)[0]+'@'+digest+'\nCOPY ["03 Software/RF-One Web/role_profile_routes.py", "/app/RF-One Web/role_profile_routes.py"]\nCOPY ["03 Software/RF-One Web/registry_clover.py", "/app/RF-One Web/registry_clover.py"]\nARG RFONE_RELEASE_REVISION\nLABEL org.opencontainers.image.revision=$RFONE_RELEASE_REVISION\n',encoding='utf-8',newline='\n')
(out/'baseline.json').write_text(json.dumps({'service_arn':v['service_arn'],'previous_image':v['image'],'previous_digest':digest},indent=2));print('Live baseline verified; only two runtime files will be copied')
